INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & transmission model', '[["Invoice format", "XML based on UBL 2.1, with a Serbia-specific CIUS aligned to EN 16931"], ["Transmission model", "Centralized clearance (CTC) -- every invoice is validated by SEF before reaching the recipient, similar to Italy''s SDI"], ["E-otpremnica format", "Also UBL 2.1-based, managed by a \"Central Information Intermediary\""], ["Access channels", "SEF/e-otpremnica national eID portal, web UI, mobile app, or API"]]', 'Unlike Slovenia''s decentralized ZIERDED model, Serbia''s SEF is a true government clearance platform -- there is no alternative permitted transmission channel for the core e-invoicing mandate.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'SEF portal & environments', '[["Production portal", "efaktura.gov.rs"], ["Test/demo environment", "demoefaktura.mfin.gov.rs"], ["E-otpremnica portal", "eotpremnica.efaktura.gov.rs"], ["Latest release", "SEF v4.1.0, released to production 2 Aug 2026"]]', 'SEF v4.0.0''s production deployment was officially postponed (announced 24 Jul 2026) with no new date given -- v4.1.0''s relationship to the delayed v4.0.0 release was not independently confirmed in this research; verify current version behaviour directly with SEF before relying on this note.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who the e-invoicing mandate covers', '[["Scope", "All VAT-registered taxpayers, and all entities using the public procurement system"], ["Size threshold", "None identified in the law''s text"], ["B2G", "Mandatory since May-July 2022"], ["B2B", "Mandatory since 1 January 2023 (issuance and receipt)"], ["VAT recording", "Electronic recording of VAT self-assessment in SEF also mandatory since 1 January 2023"]]', 'Whether B2C (consumer/retail, fiscal-receipt) invoicing falls inside or outside the e-Faktura mandate was not independently confirmed against the law''s text in this research -- secondary sources suggest it is governed separately by fiscal cash-register rules, but treat this as unconfirmed.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'E-delivery note (e-otpremnica) rollout', '[["Legal basis", "Zakon o elektronskim otpremnicama (Sl. glasnik RS 94/2024 i 109/2025) -- a separate statute from the e-invoicing law"], ["Phase 1 (1 Jan 2026)", "Public sector, excise-goods traders (fuel, alcohol, tobacco, e-cigarettes, electricity, coffee), and carriers"], ["Grace period", "Full inspection enforcement began after 30 June 2026"], ["Phase 2 (1 Oct 2027)", "Extends to general private-sector B2B goods movement"]]', 'Do not conflate e-otpremnica''s Phase 2 with the separately-reported "expanded B2B" e-invoicing reform package (new SEF fields, stricter validation, full document archiving, a new penalty regime) -- secondary sources describe that package as postponed to "end of 2026," a distinct development whose exact date could not be confirmed against a primary Ministry of Finance announcement.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ E-invoicing penalties (Arts. 18-21)', NULL, NULL, 'Zakon o elektronskom fakturisanju sets tiered fines: RSD 200,000-2,000,000 for legal entities/public enterprises (failure to issue e-invoices, improper VAT recording, or system non-compliance), RSD 50,000-500,000 for entrepreneurs, and RSD 50,000-150,000 for a responsible person within an entity, with the same ranges applying to obstruction of inspection (Art. 21) and to information intermediaries compromising system security (Art. 19). These figures come from Paragraf.rs''s consolidated legal text -- a reputable Serbian legal publisher, but a secondary compiler rather than the raw Official Gazette -- so treat exact article attribution as indicative pending direct verification of the gazette PDF text.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🚚 E-delivery-note penalties (Arts. 13-14)', NULL, NULL, 'Zakon o elektronskim otpremnicama sets its own tiered fines: RSD 200,000-2,000,000 for legal entities (private sector, carriers, public enterprises, for transmission failures, representation violations, or data-retention breaches), RSD 50,000-150,000 for responsible individuals, and RSD 50,000-500,000 for solo entrepreneurs, with flat fines for inspection obstruction (RSD 300,000 for legal entities, RSD 50,000 for responsible individuals, RSD 150,000 for solo entrepreneurs). As with the e-invoicing penalties above, these figures are sourced via Paragraf.rs''s consolidated text, not a direct read of the gazette PDF.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 What we could not confirm', NULL, NULL, 'Three items are flagged from this research round rather than presented as settled fact: (1) the exact new date for the separately-reported "expanded B2B" e-invoicing reform package, sourced only via a secondary advisory (Fiscal Solutions) citing an unlocated primary Ministry of Finance announcement; (2) the relationship between the postponed SEF v4.0.0 release and the v4.1.0 release that went to production 2 Aug 2026 -- unclear whether one supersedes or renames the other; (3) whether B2C/fiscal-receipt invoicing sits inside or outside the core e-Faktura mandate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your business already issues and receives e-invoices through SEF', 'This has been mandatory for B2B trade with Serbian counterparties since 1 January 2023 -- confirm your invoicing software or provider is SEF-connected, not relying on paper or plain PDF.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you supply excise goods or operate as a carrier in Serbia, confirm e-otpremnica readiness', 'Phase 1 of the e-delivery-note mandate (public sector, excise-goods traders, carriers) has applied since 1 January 2026, with full inspection enforcement now live after the 30 June 2026 grace period.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If your business is not yet in an e-otpremnica Phase 1 category, plan ahead of Phase 2', 'From 1 October 2027, the e-delivery-note obligation extends to general private-sector B2B goods movement -- test your process well before that date.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Track SEF version changes -- v4.0.0''s production date remains unannounced', 'The Ministry of Finance postponed SEF v4.0.0''s production deployment (announced 24 Jul 2026) without giving a new date, while a v4.1.0 release went live 2 Aug 2026 -- confirm with SEF support which version applies to your integration.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'RS';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for confirmation of the separately-reported "expanded B2B" reform package', 'New invoice fields, stricter validation, full document archiving, and a new penalty regime have been reported by secondary sources as targeting "end of 2026," but this has not been confirmed via a primary government announcement -- do not commit engineering resources against an unconfirmed date.');
